        lower_terms: &[Value],
        span: Span,
        columns_to_search: &[String],
        invert: bool,
    ) -> bool {
        let separator = self.expanded_string_separator.as_str();
        let value_span = value.span();
        let expanded = value.to_expanded_string(separator, filter_config);
        let expanded_len = expanded.len();
