        let comparable = Value::string(lowered.clone(), span);
        let comparable_span = Value::string(lowered.clone(), value_span);
        let using_call_span = comparable.span() == span || comparable_span.span() == value_span;
        let Value::Record { val, .. } = value else {
            return self.invert_match_result(false, invert);
        };
        if lower_terms.is_empty() {
            return self.invert_match_result(false, invert);
        }
        let mut matched = false;
        let mut scanned = 0usize;
        for term in lower_terms {
