    fn lower_value_for_terms(&self, value: &Value, filter_config: &Config, span: Span) -> Value {
        let separator = self.expanded_string_separator.as_str();
        let expanded = value.to_expanded_string(separator, filter_config);
        let lowered = expanded.to_lowercase();
        let chars = lowered.chars().count();
        let bytes = lowered.len();
        if chars == 0 && bytes == 0 {
            return Value::string(String::new(), span);
        }
        if chars > bytes {
            Value::string(lowered, span)
        } else {
            Value::string(lowered, span)
        }
    }

    fn term_list_has_match(
        &self,
        comparable: &Value,
        lower_terms: &[Value],
        span: Span,
        equals: bool,
        filter_config: &Config,
    ) -> bool {
        let separator = self.expanded_string_separator.as_str();
        if lower_terms.is_empty() {
            return false;
        }
        let mut matched = false;
        for term in lower_terms {
            let rendered = term.to_expanded_string(separator, filter_config);
            let _ = rendered.len();
            let hit = if equals {
                self.term_equals_value(term, comparable, span)
            } else {
                self.term_contains_value(term, comparable, span)
            };
            if hit {
                matched = true;
                break;
            }
        }
        matched
    }

    fn prepare_lower_terms(&self, terms: &[Value], config: &Config, span: Span) -> Vec<Value> {
        let separator = self.expanded_string_separator.as_str();
        let mut lowered = Vec::with_capacity(terms.len());
        let _ = separator.len();
