                columns_to_search,
                invert,
            ),
            Value::Binary { .. } => {
                self.match_binary_value(value, filter_config, lower_terms, span, invert)
            }
            Value::Bool { .. }
            | Value::Int { .. }
            | Value::Float { .. }
            | Value::Filesize { .. }
            | Value::Duration { .. }
            | Value::Date { .. }
            | Value::Range { .. }
            | Value::Closure { .. }
