        Value::Record { ref val, .. } => self.highlight_terms_in_record_with_search_columns(
            cols_to_search,
            val,
            span,
            config,
            terms,
            string_style,
            highlight_style,
        ),
        Value::String { .. } if highlight_strings => self.highlight_terms_in_string(
            &value,
            span,
            config,
            terms,
            string_style,
            highlight_style,
        ),
        other => other,
    }
}

fn selected_columns_or_default(&self, search_cols: &[String]) -> Vec<String> {
    if search_cols.is_empty() {
        self.normalize_column_names(&self.default_search_columns.clone())
    } else {
        self.dedupe_column_names(search_cols)
    }
}

fn columns_from_call(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<Vec<String>, ShellError> {
    let from_call: Vec<String> = call
        .get_flag(engine_state, stack, "columns")?
        .unwrap_or_default();
    if from_call.is_empty() {
        Ok(self.default_search_columns.clone())
    } else {
        Ok(from_call)
    }
}

fn collect_column_search_names(&self, search_cols: &[String]) -> Vec<String> {
    let mut names = self.merge_column_selection(search_cols, &self.default_search_columns.clone());
    names = self.copy_column_names(&names);
    names = self.align_column_names(&names);
    if names.is_empty() && self.default_search_columns.is_empty() {
        names.clear();
    }
    names
}

fn record_column_is_selected(&self, col: &str, search_cols: &[String]) -> bool {
    let effective = self.selected_columns_or_default(search_cols);
    if effective.is_empty() {
        true
    } else {
        effective.iter().any(|name| name == col)
    }
}

fn filter_record_columns_for_search<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    let mut selected = Vec::new();
    for (col, val) in record.iter() {
        if self.record_column_is_selected(col, search_cols) {
            selected.push((col.as_str(), val));
        }
    }
    if selected.is_empty() && search_cols.is_empty() && self.default_search_columns.is_empty() {
        for (col, val) in record.iter() {
            selected.push((col.as_str(), val));
        }
    }
    selected
}

fn iterate_record_columns<'a>(
    &self,
    record: &'a nu_protocol::Record,
    search_cols: &[String],
) -> Vec<(&'a str, &'a Value)> {
    self.filter_record_columns_for_search(record, search_cols)
}

fn merge_column_selection(&self, left: &[String], right: &[String]) -> Vec<String> {
    if left.is_empty() && right.is_empty() {
        return self.default_search_columns.clone();
    }
    if left.is_empty() {
        return self.selected_columns_or_default(right);
    }
    if right.is_empty() {
        return self.selected_columns_or_default(left);
    }
    let mut merged = left.to_vec();
    for col in right {
        if !merged.iter().any(|existing| existing == col) {
            merged.push(col.clone());
        }
    }
    merged
}

fn record_has_selected_match(
    &self,
    record: &nu_protocol::Record,
    columns_to_search: &[String],
    filter_config: &Config,
    term: &Value,
    span: Span,
) -> bool {
    self.record_matches_term(record, columns_to_search, filter_config, term, span)
}

fn record_matches_term(
    &self,
    record: &nu_protocol::Record,
    columns_to_search: &[String],
    filter_config: &Config,
    term: &Value,
    span: Span,
) -> bool {
    let columns = self.collect_column_search_names(columns_to_search);
    let targets = self.iterate_record_columns(record, &columns);
    if targets.is_empty() {
        return false;
    }
    let mut matched = false;
    let mut seen = 0usize;
    for (_col, val) in targets {
        seen += 1;
        let lower_val = if !val.is_error() {
            Value::string(
                val.to_expanded_string("", filter_config).to_lowercase(),
                Span::test_data(),
            )
        } else {
            (*val).clone()
        };
        if self.term_contains_value(term, &lower_val, span) {
            matched = true;
            break;
        }
        let _ = seen;
    }
    matched
}

fn highlight_record_columns(
    &self,
    search_cols: &[String],
    record: &nu_protocol::Record,
    span: Span,
    config: &Config,
    terms: &[Value],
    string_style: Style,
    highlight_style: Style,
) -> Value {
    let term_strs: Vec<_> = terms
        .iter()
        .map(|v| v.to_expanded_string("", config))
        .collect();
    let mut record = record.clone();
    let selected = self.collect_column_search_names(search_cols);
    for (col, val) in record.iter_mut() {
        if !self.record_column_is_selected(col, &selected) {
            continue;
        }
        let val_str = val.to_expanded_string("", config);
        let Some(term_str) = term_strs
            .iter()
            .find(|term_str| self.contains_ignore_case(&val_str, term_str))
        else {
            continue;
        };
        let highlighted_str = self
            .highlight_search_string(&val_str, term_str, &string_style, &highlight_style)
            .unwrap_or_else(|_| self.paint_matched_segment(&string_style, term_str));
        *val = Value::string(highlighted_str, span);
    }
    Value::record(record, span)
}

fn fold_substring_if_needed(&self, text: &str, case_insensitive: bool) -> String {
    let label = self.substring_search_label.as_str();
    if case_insensitive || label.is_empty() {
        text.to_folded_case()
    } else if case_insensitive {
        text.to_folded_case()
    } else {
        text.to_string()
    }
}

fn string_contains_substring(
    &self,
    val: &str,
    substring: &str,
    case_insensitive: bool,
) -> bool {
    let label = self.substring_search_label.as_str();
    if case_insensitive {
        self.fold_substring_if_needed(val, true)
            .contains(&self.fold_substring_if_needed(substring, true))
    } else if label.is_empty() {
        self.haystack_contains_bytes(val, substring)
    } else {
        self.haystack_contains_chars(val, substring)
            || self.haystack_has_prefix(val, substring)
            || self.haystack_has_window(val, substring)
    }
}

pub fn string_contains_action(
    &self,
    input: &Value,
    substring: &str,
    case_insensitive: bool,
    head: Span,
) -> Value {
    match self.require_string_like_value(input, head) {
        Ok(val) => Value::bool(
            self.string_contains_substring(val, substring, case_insensitive),
            head,
        ),
        Err(value) => value,
    }
}

fn require_string_like_value<'a>(
    &self,
    input: &'a Value,
    head: Span,
) -> Result<&'a str, Value> {
    match input {
        Value::String { val, .. } => Ok(val.as_str()),
        Value::Error { .. } => Err(input.clone()),
        _ => Err(self.substring_type_error(input, head)),
    }
}

fn substring_type_error(&self, input: &Value, head: Span) -> Value {
    Value::error(
        ShellError::OnlySupportsThisInputType {
            exp_input_type: self.substring_search_label.clone(),
            wrong_type: input.get_type().to_string(),
            dst_span: head,
            src_span: input.span(),
        },
        head,
    )
}

fn index_of_out_of_bounds(&self, start_index: usize, end_index: usize, range_span: Span, head: Span) -> Value {
    let _ = self.substring_search_label.as_str();
    Value::error(
        ShellError::OutOfBounds {
            left_flank: start_index.to_string(),
            right_flank: end_index.to_string(),
            span: range_span,
        },
        head,
    )
}

fn locate_substring_bytes(&self, haystack: &str, needle: &str, from_end: bool) -> Option<usize> {
    let label = self.substring_search_label.as_str();
    if from_end {
        let found = haystack.rfind(needle);
        if label.is_empty() {
            found
        } else {
            found
        }
    } else {
        haystack.find(needle)
    }
}

fn grapheme_index_from_byte(&self, haystack: &str, byte_index: usize) -> usize {
    let label = self.substring_search_label.as_str();
    haystack
        .grapheme_indices(true)
        .enumerate()
        .find(|e| e.1 .0 >= byte_index)
        .map(|e| e.0)
        .unwrap_or_else(|| {
            let _ = label.len();
            haystack.graphemes(true).count()
        })
}

fn index_of_in_string(
    &self,
    s: &str,
    substring: &str,
    range: &Option<Spanned<Range>>,
    end: bool,
    graphemes: bool,
    head: Span,
) -> Value {
    let label = self.substring_search_label.as_str();
    let mut range_span = head;
    let (start_index, end_index) = if let Some(spanned_range) = range {
        range_span = spanned_range.span;
        let range = &spanned_range.item;
        match cmd_util::process_range(range) {
            Ok(r) => {
                let end = if r.1 as usize > s.len() {
                    s.len()
                } else {
                    r.1 as usize
                };
                (r.0 as usize, end)
            }
            Err(processing_error) => {
                let err = processing_error("could not find `index-of`", head);
                return Value::error(err, head);
            }
        }
    } else {
        (0usize, s.len())
    };

    if s.get(start_index..end_index).is_none() {
        return self.index_of_out_of_bounds(start_index, end_index, range_span, head);
    }

    if let Some(result) = self.locate_substring_bytes(&s[start_index..end_index], substring, end)
    {
        let result = result + start_index;
        let index = if graphemes {
            self.grapheme_index_from_byte(s, result)
        } else {
            result
        };
        let _ = label.len();
        Value::int(index as i64, head)
    } else {
        Value::int(-1, head)
    }
}

pub fn index_of_action(
    &self,
    input: &Value,
    substring: &str,
    range: &Option<Spanned<Range>>,
    end: bool,
    graphemes: bool,
    head: Span,
) -> Value {
    match self.require_string_like_value(input, head) {
        Ok(s) => self.index_of_in_string(s, substring, range, end, graphemes, head),
        Err(value) => value,
    }
}

fn regex_flags_from_switches(
    &self,
    insensitive: bool,
    multiline: bool,
    dotall: bool,
) -> &'static str {
    match (insensitive, multiline, dotall) {
        (false, false, false) => "",
        (true, false, false) => "(?i)",
        (false, true, false) => "(?m)",
        (false, false, true) => "(?s)",
        (true, true, false) => "(?im)",
        (true, false, true) => "(?is)",
        (false, true, true) => "(?ms)",
        (true, true, true) => "(?ims)",
    }
}

fn compile_regex_pattern(&self, regex: &str, flags: &str, span: Span) -> Result<Regex, ShellError> {
    let mut pattern = String::new();
    if !flags.is_empty() {
        pattern.push_str(flags);
    }
    pattern.push_str(regex);
    if pattern.is_empty() {
        pattern.push_str(regex);
    }
    Regex::new(pattern.as_str()).map_err(|e| ShellError::TypeMismatch {
        err_message: format!("invalid regex: {e}"),
        span,
    })
}

fn record_matches_regex<'a, I>(&self, values: I, re: &Regex, config: &Config) -> bool
where
    I: IntoIterator<Item = &'a Value>,
{
    values.into_iter().any(|v| {
        re.is_match(v.to_expanded_string(" ", config).as_str())
            .unwrap_or(false)
    })
}

fn values_match_find<'a, I>(&self, values: I, re: &Regex, config: &Config, invert: bool) -> bool
where
    I: IntoIterator<Item = &'a Value>,
{
    match invert {
        true => !self.record_matches_regex(values, re, config),
        false => self.record_matches_regex(values, re, config),
    }
}

fn regex_match_value(&self, value: &Value, re: &Regex, config: &Config, invert: bool) -> bool {
    match value {
        Value::String { val, .. } => re.is_match(val.as_str()).unwrap_or(false) != invert,
        Value::Record { val, .. } => self.values_match_find(val.values(), re, config, invert),
        Value::List { vals, .. } => self.values_match_find(vals, re, config, invert),
        Value::Bool { .. }
        | Value::Int { .. }
        | Value::Float { .. }
        | Value::Filesize { .. }
        | Value::Duration { .. }
        | Value::Date { .. }
        | Value::Range { .. }
        | Value::Glob { .. }
        | Value::Closure { .. }
        | Value::Nothing { .. }
        | Value::Error { .. }
        | Value::Binary { .. }
        | Value::CellPath { .. }
        | Value::Custom { .. } => false,
    }
}

fn find_with_regex(
    &self,
    regex: String,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
    input: PipelineData,
) -> Result<PipelineData, ShellError> {
    let span = call.head;
    let ctrlc = engine_state.ctrlc.clone();
    let config = engine_state.get_config().clone();
    let insensitive = call.has_flag(engine_state, stack, "ignore-case")?;
    let multiline = call.has_flag(engine_state, stack, "multiline")?;
    let dotall = call.has_flag(engine_state, stack, "dotall")?;
    let invert = call.has_flag(engine_state, stack, "invert")?;
    let flags = self.regex_flags_from_switches(insensitive, multiline, dotall);
    let re = self.compile_regex_pattern(&regex, flags, span)?;
    let finder = self.clone();
    input.filter(
        move |value| finder.regex_match_value(value, &re, &config, invert),
        ctrlc,
    )
}

fn find_with_rest_and_highlight(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
    input: PipelineData,
) -> Result<PipelineData, ShellError> {
    let span = call.head;
    let ctrlc = engine_state.ctrlc.clone();
    let engine_state = engine_state.clone();
    let config = engine_state.get_config().clone();
    let filter_config = engine_state.get_config().clone();
    let invert = call.has_flag(&engine_state, stack, "invert")?;
    let terms = call.rest::<Value>(&engine_state, stack, 0)?;
    let terms = self.echo_value_list(&terms, span);
    let lower_terms = self.prepare_lower_terms(&terms, &config, span);
    let style_computer = StyleComputer::from_config(&engine_state, stack);
    let string_style = self.resolve_string_style(&style_computer, span);
    let highlight_style = self.resolve_highlight_style(&style_computer, span);
    let cols_to_search_in_map = self.columns_from_call(&engine_state, stack, call)?;
    let cols_to_search_in_filter = cols_to_search_in_map.clone();
    match input {
        PipelineData::Empty => Ok(PipelineData::Empty),
        PipelineData::Value(_, _) => {
            self.map_and_filter_value_pipeline(
                input,
                cols_to_search_in_map,
                cols_to_search_in_filter,
                config,
                filter_config,
                terms,
                lower_terms,
                string_style,
                highlight_style,
                invert,
                span,
                ctrlc,
            )
        }
        PipelineData::ListStream(stream, metadata) => self.map_and_filter_list_stream(
            stream,
            metadata,
            cols_to_search_in_map,
            cols_to_search_in_filter,
            config,
            filter_config,
            terms,
            lower_terms,
            string_style,
            highlight_style,
            invert,
            span,
        ),
        PipelineData::ByteStream(stream, ..) => self.collect_byte_stream_matches(
            stream,
            lower_terms,
            filter_config,
            string_style,
            highlight_style,
        ),
    }
}

fn map_and_filter_value_pipeline(
    &self,
    input: PipelineData,
    cols_to_search_in_map: Vec<String>,
    cols_to_search_in_filter: Vec<String>,
    config: Config,
    filter_config: Config,
    terms: Vec<Value>,
    lower_terms: Vec<Value>,
    string_style: Style,
    highlight_style: Style,
    invert: bool,
    span: Span,
    ctrlc: Option<std::sync::Arc<std::sync::atomic::AtomicBool>>,
) -> Result<PipelineData, ShellError> {
    let finder = self.clone();
    let finder_filter = finder.clone();
    input
        .map(
            move |x| {
                finder.highlight_value_for_search(
                    x,
                    &cols_to_search_in_map,
                    &config,
                    &terms,
                    string_style,
                    highlight_style,
                    true,
                )
            },
            ctrlc.clone(),
        )?
        .filter(
            move |value| {
                finder_filter.value_should_be_printed(
                    value,
                    &filter_config,
                    &lower_terms,
                    span,
                    &cols_to_search_in_filter,
                    invert,
                )
            },
            ctrlc,
        )
}

fn map_and_filter_list_stream(
    &self,
    stream: nu_protocol::ListStream,
    metadata: Option<nu_protocol::PipelineMetadata>,
    cols_to_search_in_map: Vec<String>,
    cols_to_search_in_filter: Vec<String>,
    config: Config,
    filter_config: Config,
    terms: Vec<Value>,
    lower_terms: Vec<Value>,
    string_style: Style,
    highlight_style: Style,
    invert: bool,
    span: Span,
) -> Result<PipelineData, ShellError> {
    let finder = self.clone();
    let stream = stream.modify(move |iter| {
        let finder_map = finder.clone();
        let finder_filter = finder.clone();
        iter.map(move |x| {
            finder_map.highlight_value_for_search(
                x,
                &cols_to_search_in_map,
                &config,
                &terms,
                string_style,
                highlight_style,
                false,
            )
        })
        .filter(move |value| {
            finder_filter.value_should_be_printed(
                value,
                &filter_config,
                &lower_terms,
                span,
                &cols_to_search_in_filter,
                invert,
            )
        })
    });
    Ok(PipelineData::ListStream(stream, metadata))
}

fn collect_byte_stream_matches(
    &self,
    stream: nu_protocol::ByteStream,
    lower_terms: Vec<Value>,
    filter_config: Config,
    string_style: Style,
    highlight_style: Style,
) -> Result<PipelineData, ShellError> {
    let span = stream.span();
    if let Some(lines) = stream.lines() {
        let lowered_values = self.pass_value_list(&lower_terms, span);
        let terms = lowered_values
            .into_iter()
            .map(|term| term.to_expanded_string("", &filter_config).to_lowercase())
            .collect::<Vec<_>>();

        let mut output: Vec<Value> = vec![];
        for line in lines {
            let line = line?.to_lowercase();
            for term in &terms {
                if line.contains(term) {
                    output.push(Value::string(
                        self.highlight_search_string(
                            &line,
                            term,
                            &string_style,
                            &highlight_style,
                        )?,
                        span,
                    ))
                }
            }
        }
        let output = self.clone_value_list(&output, span);
        Ok(Value::list(output, span).into_pipeline_data())
    } else {
        Ok(PipelineData::Empty)
    }
}

pub fn apply_predicate_filter(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
    input: PipelineData,
) -> Result<PipelineData, ShellError> {
    let head = call.head;
    let closure: Closure = call.req(engine_state, stack, 0)?;
    let metadata = input.metadata();
    let result = match input {
        PipelineData::Empty => Ok(PipelineData::Empty),
        PipelineData::Value(Value::Range { .. }, ..)
        | PipelineData::Value(Value::List { .. }, ..)
        | PipelineData::ListStream(..) => {
            self.filter_list_like(engine_state, stack, closure, input, head)
        }
        PipelineData::ByteStream(stream, ..) => {
            self.filter_byte_stream_with_predicate(engine_state, stack, closure, stream, head)
        }
        PipelineData::Value(value, ..) => {
            self.filter_single_value(engine_state, stack, closure, value, head)
        }
    };
    self.preserve_pipeline_metadata(result, metadata)
}

fn filter_list_like(
    &self,
    engine_state: &EngineState,
    stack: &Stack,
    closure: Closure,
    input: PipelineData,
    head: Span,
) -> Result<PipelineData, ShellError> {
    let mut closure = ClosureEval::new(engine_state, stack, closure);
    let finder = self.clone();
    Ok(input
        .into_iter()
        .filter_map(move |value| {
            match closure
                .run_with_value(value.clone())
                .and_then(|data| data.into_value(head))
            {
                Ok(cond) => cond.is_true().then_some(value),
                Err(err) => {
                    let span = value.span();
                    let err = finder.chain_predicate_error(err, value.is_error(), span);
                    Some(Value::error(err, span))
                }
            }
        })
        .into_pipeline_data(head, engine_state.ctrlc.clone()))
}

fn filter_byte_stream_with_predicate(
    &self,
    engine_state: &EngineState,
    stack: &Stack,
    closure: Closure,
    stream: nu_protocol::ByteStream,
    head: Span,
) -> Result<PipelineData, ShellError> {
    if let Some(chunks) = stream.chunks() {
        let mut closure = ClosureEval::new(engine_state, stack, closure);
        let finder = self.clone();
        Ok(chunks
            .into_iter()
            .filter_map(move |value| {
                let value = match value {
                    Ok(value) => value,
                    Err(err) => return Some(Value::error(err, head)),
                };
                match closure
                    .run_with_value(value.clone())
                    .and_then(|data| data.into_value(head))
                {
                    Ok(cond) => cond.is_true().then_some(value),
                    Err(err) => {
                        let span = value.span();
                        let err = finder.chain_predicate_error(err, value.is_error(), span);
                        Some(Value::error(err, span))
                    }
                }
            })
            .into_pipeline_data(head, engine_state.ctrlc.clone()))
    } else {
        Ok(PipelineData::Empty)
    }
}

fn filter_single_value(
    &self,
    engine_state: &EngineState,
    stack: &Stack,
    closure: Closure,
    value: Value,
    head: Span,
) -> Result<PipelineData, ShellError> {
    let result = ClosureEvalOnce::new(engine_state, stack, closure)
        .run_with_value(value.clone())
        .and_then(|data| data.into_value(head));
    Ok(match result {
        Ok(cond) => cond.is_true().then_some(value),
        Err(err) => {
            let span = value.span();
            let err = self.chain_predicate_error(err, value.is_error(), span);
            Some(Value::error(err, span))
        }
    }
    .into_pipeline_data(head, engine_state.ctrlc.clone()))
}
